/**
 * Region geometry shared by both data modes: REAL public boundaries (IBGE Malha Municipal 2025, simplified).
 * Generated by tools/mock_geo/gerar_geometria_tocantins.py. No activity data lives here.
 */
import contorno from './tocantins-contorno.json' with { type: 'json' }
import municipios from './tocantins-municipios.json' with { type: 'json' }
import type { Feature, FeatureCollection } from 'geojson'
import type { Cell, Region } from '../types'
import { pointInRing, ringBounds, type LonLat } from '../lib/geo'

export const CELL_SIZE = 0.25

export const OUTLINE_RING = (contorno as unknown as { geometry: { coordinates: LonLat[][] } }).geometry.coordinates[0]
export const MUNICIPALITIES = municipios as unknown as FeatureCollection
export const OUTLINE_FEATURE = contorno as unknown as Feature

const [w, s, e, n] = ringBounds(OUTLINE_RING)

export const REGION: Region = {
  id: 'BR-TO',
  name: 'Tocantins',
  country: 'BR',
  bbox: [w, s, e, n],
  cellSizeDeg: CELL_SIZE,
}

/** Cell of the 0.25 degree grid anchored at (0, 0): [i*0.25, (i+1)*0.25) in latitude, same for longitude (same rule as the processing). */
export function makeCell(i: number, j: number): Cell {
  const lat0 = i * CELL_SIZE
  const lon0 = j * CELL_SIZE
  const boundary = !pointInRing(lon0 + CELL_SIZE / 2, lat0 + CELL_SIZE / 2, OUTLINE_RING)
  return { id: `g0.25_${i}_${j}`, i, j, lat0, lon0, lat1: lat0 + CELL_SIZE, lon1: lon0 + CELL_SIZE, boundary }
}

export function cellFeatureCollection(cells: Cell[], properties: (c: Cell, idx: number) => Record<string, unknown>): FeatureCollection {
  return {
    type: 'FeatureCollection',
    features: cells.map((c, idx) => ({
      type: 'Feature',
      id: idx,
      properties: { id: c.id, boundary: c.boundary ? 1 : 0, ...properties(c, idx) },
      geometry: {
        type: 'Polygon',
        coordinates: [[[c.lon0, c.lat0], [c.lon1, c.lat0], [c.lon1, c.lat1], [c.lon0, c.lat1], [c.lon0, c.lat0]]],
      },
    })),
  }
}
